contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run test: take a candidate owner, a recipient, and an amount to fund contract
    function run(address candidateOwner, address recipient, uint256 fund) public payable {
        require(address(this).balance >= fund);

        // Deploy-time: c was already deployed by the harness with some owner; we only interact via its public surface.
        // Fund contract c by sending Ether to it from this test contract
        if (fund > 0) {
            // send Ether to c using its fallback (payable)
            (bool ok,) = address(c).call{value: fund}("");
            require(ok);
        }

        // Read owner and balances before attempt
        address ownerBefore = c.owner();
        uint256 cBalanceBefore = address(c).balance;
        uint256 thisBalanceBefore = address(this).balance;

        // Attempt withdrawAll as this contract (msg.sender for c will be InvMutTest)
        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-state
        address ownerAfter = c.owner();
        uint256 cBalanceAfter = address(c).balance;
        uint256 thisBalanceAfter = address(this).balance;

        // General rule/assertion:
        // - The owner field never changes due to withdrawAll.
        // - If the caller (this contract) is the owner, then withdrawAll must not revert and contract's entire balance should be transferred out (so cBalanceAfter == 0 and recipient received funds).
        // - If the caller is not the owner, withdrawAll must revert and balances must be unchanged.
        // We observe recipient's balance change indirectly: when this contract calls withdrawAll and it succeeds, c's balance goes to 0 and this contract's balance increases only if recipient == address(this).
        // To make the rule universally checkable with only observable values, we assert owner stability and the correlation between (caller==owner) and revert + c balance change.
        assert(ownerBefore == ownerAfter && (
            ((address(this) == ownerBefore) && !reverted && cBalanceAfter == 0) ||
            ((address(this) != ownerBefore) && reverted && cBalanceAfter == cBalanceBefore)
        ));
    }

    // allow receiving Ether
    receive() external payable {}
}

