contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking parameters: owner (must match deployed c.owner), caller (unused since calls come from this contract), recipient and an amount to send to c before withdraw
    function run(address maybeOwner, address recipient, uint256 fund) public payable {
        require(true);
        // We must fund this test contract so it can forward Ether to c. Ensure we have enough balance to send `fund`.
        // The checker will provide Ether to this call if desired; enforce the available balance precondition.
        require(address(this).balance >= fund);

        // Read the declared owner of c before any action
        address ownerBefore = c.owner();

        // Fund contract c by sending Ether from this contract
        // Use low-level call via payable address(c).call{value: fund} to invoke fallback and deposit Ether
        (bool sent,) = address(c).call{value: fund}("");
        // The deposit should always succeed for this contract's fallback which is payable
        require(sent);

        // Record balances before withdraw attempt
        uint256 cBalanceBefore = address(c).balance;
        uint256 thisBalanceBefore = address(this).balance;

        // Attempt withdrawAll and capture whether it reverted. According to C, only owner can withdraw.
        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read balances and owner after the call
        uint256 cBalanceAfter = address(c).balance;
        uint256 thisBalanceAfter = address(this).balance;
        address ownerAfter = c.owner();

        // General rule asserting correct behavior for both owner and non-owner callers:
        // - owner is immutable
        // - if the call did not revert then c's entire previous balance must have been transferred:
        //     cBalanceAfter == 0 and this contract's balance increased by cBalanceBefore (minus 0 since transfer goes to recipient)
        //   but since withdrawAll sends to `recipient`, the test contract's balance only changes if recipient == address(this).
        // - if the call reverted then balances remain unchanged (no Ether moved) and owner unchanged.
        // Thus combine into one assertion:
        assert(ownerBefore == ownerAfter
            && (reverted
                ? (cBalanceAfter == cBalanceBefore && thisBalanceAfter == thisBalanceBefore)
                : (cBalanceAfter == 0 && (
                      // If recipient equals this contract, this contract should receive the funds
                      (recipient == address(this) ? thisBalanceAfter == thisBalanceBefore + cBalanceBefore : thisBalanceAfter == thisBalanceBefore)
                   )
                )
            )
        );
    }

    // allow receiving Ether if withdraw sends to this contract
    receive() external payable { }
}

