    function run(address possibleOwner, address payable recipient, uint funding) public payable {
        require(address(this).balance >= funding);

        // Initialize contract state: contract C was already deployed and passed in constructor.
        // We cannot change c.owner except via its constructor, so we observe its current owner.
        address beforeOwner = c.owner();
        // Fund contract c by sending Ether to it from this test contract
        if (funding > 0) {
            // transfer Ether to c using low-level call to trigger fallback
            (bool sent,) = address(c).call{value: funding}("");
            // ignore whether funding succeeded; address(c).balance reflects actual funding
        }

        // Attempt to call withdrawAll as this contract (msg.sender will be this contract)
        bool reverted;
        uint balBefore = address(c).balance;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint balAfter = address(c).balance;
        address ownerAfter = c.owner();

        // General rule:
        // If the call reverted then contract balance must be unchanged and owner unchanged.
        // Otherwise (call succeeded) the entire previous balance must have been sent to recipient
        // (so c.balance decreased by balBefore) and owner remains unchanged.
        assert(
            ownerAfter == beforeOwner &&
            (reverted ? balAfter == balBefore : balBefore > 0 ? balAfter == 0 && address(this).balance + 0 >= 0 : balAfter == 0)
        );
    }

    receive() external payable {}
}

