contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that is payable to allow funding this test contract
    function run(address ownerAddr, address payable recipient, uint fundAmount, bool callAsOwner) public payable {
        require(address(this).balance >= fundAmount);
        // The fresh C is already deployed by the checker with some owner; we must not assume it.
        // However, per the problem statement, the checker deploys a FRESH c and passes it in constructor.
        // We will perform actions as the InvMutTest contract (msg.sender to c).

        // Fund contract C with fundAmount wei from this test contract
        // ensure we have the funds
        if (fundAmount > 0) {
            // transfer Ether to c to change its balance
            (bool sent,) = address(c).call{value: fundAmount}("");
            require(sent);
        }

        // Record balance before
        uint beforeBalance = address(c).balance;

        // Decide who should be the caller: if callAsOwner==true, we must call as the owner
        // But we cannot change msg.sender. The only way to simulate owner-call is if c.owner() == address(this).
        // So we read owner and branch expectation accordingly.
        address currentOwner = c.owner();

        bool shouldSucceed = (callAsOwner && currentOwner == address(this));

        bool reverted;
        // Make the call and observe revert status
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterBalance = address(c).balance;

        // General rule: if call was made by owner (i.e., currentOwner == address(this)) then withdraw succeeds (no revert),
        // and contract balance becomes zero while recipient receives the previous balance; otherwise it reverts and balance unchanged.
        // We cannot directly read recipient's balance change reliably (external address may be arbitrary), but we can assert balance of C.

        assert((!reverted && currentOwner == address(this) && afterBalance == 0) || (reverted && afterBalance == beforeBalance));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public function with all test logic
    function run(address payable recipient, uint fundAmount, bool attemptWithdraw) public payable {
        // allow funding this test contract externally; require enough balance to fund c if requested
        require(address(this).balance >= fundAmount);

        // Fund contract C with fundAmount wei from this test contract, if any
        if (fundAmount > 0) {
            (bool sent, ) = address(c).call{value: fundAmount}("");
            require(sent);
        }

        // Observe owner and balance before attempting withdraw
        address currentOwner = c.owner(); // view call
        uint beforeBalance = address(c).balance;

        bool reverted;
        // If attemptWithdraw is true we perform the state-changing call; otherwise we skip it.
        if (attemptWithdraw) {
            // perform top-level external call and capture revert via try/catch
            try c.withdrawAll(recipient) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // no call performed
            reverted = false;
        }

        uint afterBalance = address(c).balance;

        // General invariant:
        // - If we performed the withdraw (attemptWithdraw==true) and caller was the owner (currentOwner == address(this)), it must not revert and contract balance becomes zero.
        // - If we performed the withdraw and caller was not the owner, it must revert and contract balance stays the same.
        // - If we did not perform the withdraw, balance must be unchanged and not considered a revert.
        assert(
            // case: no withdraw attempted
            (!attemptWithdraw && !reverted && afterBalance == beforeBalance)
            ||
            // case: withdraw attempted and caller was owner -> should succeed and drain to zero
            (attemptWithdraw && !reverted && currentOwner == address(this) && afterBalance == 0)
            ||
            // case: withdraw attempted and caller not owner -> should revert and balance unchanged
            (attemptWithdraw && reverted && currentOwner != address(this) && afterBalance == beforeBalance)
        );
    }

    receive() external payable {}
}

